using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Discriminator property renamed from "Discriminator" to "$type".
        // Preserve the old property name so existing documents are still readable.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Id format changed from "EntityType|Key" to just "Key".
        // Preserve the old format so existing documents (e.g. "Blog|1") still match.
        modelBuilder.Entity<Blog>().HasIdProperty(b => b.Id, IdPropertyJsonName.id)
            .Property(b => b.Id)
            .HasValueGenerator<LegacyCosmosIdGenerator>();

        // Breaking change 3: HasIndex() now throws for Cosmos DB.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // Value generator that preserves the EF Core 8 "Discriminator|Key" id format
    class LegacyCosmosIdGenerator : Microsoft.EntityFrameworkCore.ValueGeneration.ValueGenerator<string>
    {
        public override bool GeneratesTemporaryValues => false;
        public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
            => $"{entry.Metadata.ShortName()}|{entry.Property("Id").CurrentValue}";
    }
}

